query AdsPurchaseCandidateCount($all: String!, $web: String!, $paid: String!) {
  shop { id name ianaTimezone }
  allNewOrders: ordersCount(query: $all, limit: null) { count precision }
  nonTestWebOrders: ordersCount(query: $web, limit: null) { count precision }
  paidNonTestWebOrders: ordersCount(query: $paid, limit: null) { count precision }
}
